import { Container, Sprite, Text } from 'pixi.js';
import gsap from 'gsap';

import { AssetManager } from '@game-studio/asset-manager';

import { messageTextStyle } from '../../layout/text-style';

export type HTPNudgeState = 'never-shown' | 'shown' | 'hidden' | 'permanently-disabled';

export class HTPNudgeView extends Container {
    private bubbleSprite: Sprite;
    private bubbleText: Text;
    private animationTimeline: gsap.core.Timeline;
    /** Tracks the currently running animateOn or animateOff promise so dismiss() can await it */
    private currentAnimationPromise: Promise<void> = Promise.resolve();

    private nudgeState: HTPNudgeState = 'never-shown';

    private static readonly PADDING_PERCENTAGE = 0.15; // 15% padding on each side
    /** Fraction of the total texture height occupied by the pointer (below the body) */
    private static readonly POINTER_HEIGHT_RATIO = 0.19;
    /** Horizontal position of the pointer tip in the texture: 0 = left edge, 0.5 = centre, 1 = right edge */
    private static readonly POINTER_X_RATIO = 0.425;
    private static readonly ANIMATION_RISE_DURATION = 0.42; // Rise up and fade in
    private static readonly ANIMATION_SETTLE_DURATION = 0.18; // Settle to final position

    public get state(): HTPNudgeState { return this.nudgeState; }

    constructor(labelText: string) {
        super();

        this.createBubble();
        this.createText(labelText);
        this.createAnimationTimeline();

        this.name = 'htp-nudge';
    }

    /**
     * Updates the size of the bubble while maintaining text fit
     * @param width - The width of the bubble
     * @param height - The height of the bubble
     */
    public resize(width: number, height: number): void {
        this.bubbleSprite.width = width;
        this.bubbleSprite.height = height;

        // anchor is at the pointer tip (POINTER_X_RATIO, 1).
        // Body centre x: shift from sprite centre to pointer tip.
        // Body centre y: midpoint of the body portion (above the pointer).
        const bodyCentreX = (0.5 - HTPNudgeView.POINTER_X_RATIO) * width;
        const bodyCentreY = -height * (1 + HTPNudgeView.POINTER_HEIGHT_RATIO) * 0.5;

        this.bubbleText.position.set(bodyCentreX, bodyCentreY);

        this.scaleTextToFit();
    }

    /**
     * Animates the bubble appearing from the cabinet edge
     */
    public animateOn(): Promise<void> {
        this.currentAnimationPromise = new Promise<void>((resolve) => {
            if (!this.animationTimeline || this.nudgeState === 'permanently-disabled') {
                return resolve();
            }

            // Complete any current animation instantly before starting
            if (this.animationTimeline.isActive()) {
                this.animationTimeline.progress(this.animationTimeline.reversed() ? 0 : 1);
            }

            this.nudgeState = 'shown';
            this.visible = true;
            this.animationTimeline.play().then(() => resolve());
        });

        return this.currentAnimationPromise;
    }

    /**
     * Animates the bubble collapsing back into the cabinet
     */
    public animateOff(): Promise<void> {
        this.currentAnimationPromise = new Promise<void>((resolve) => {
            if (!this.animationTimeline || this.nudgeState === 'permanently-disabled') {
                return resolve();
            }

            // Complete any current animation instantly before starting
            if (this.animationTimeline.isActive()) {
                this.animationTimeline.progress(this.animationTimeline.reversed() ? 0 : 1);
            }

            this.nudgeState = 'hidden';
            this.visible = true;
            this.animationTimeline.reverse().then(() => resolve());
        });

        return this.currentAnimationPromise;
    }

    /** Permanently disables the nudge instantly, without animation */
    public disable(): void {
        this.nudgeState = 'permanently-disabled';
        this.alpha = 0;
        this.visible = false;
    }

    /**
     * Permanently dismisses the nudge — it will never show again.
     * - Animating on -> lets it finish naturally, then animates off gracefully.
     * - Fully shown -> animates off gracefully.
     * - Hidden / never-shown -> disables instantly.
     */
    public async dismiss(): Promise<void> {
        if (this.nudgeState === 'permanently-disabled') { return; }

        if (this.nudgeState === 'shown') {
            await this.currentAnimationPromise;
            await this.animateOff();
        }

        this.disable();
    }

    /**
     * Creates the animation timeline (plays forward for show, reverse for hide)
     */
    private createAnimationTimeline(): void {
        this.animationTimeline = gsap.timeline({ paused: true });

        // Rise up and fade in (from hidden state below cabinet)
        this.animationTimeline.fromTo(this,
            {
                y: () => { return this.bubbleSprite.height * 1.2; },
                alpha: 0
            },
            {
                duration: HTPNudgeView.ANIMATION_RISE_DURATION,
                y: () => { return -this.bubbleSprite.height * 0.08; },
                alpha: 1,
                ease: 'power2.out'
            }, 0);

        // Settle to final position
        this.animationTimeline.to(this, {
            duration: HTPNudgeView.ANIMATION_SETTLE_DURATION,
            y: 0,
            ease: 'power1.inOut'
        });
    }

    private createBubble(): void {
        this.bubbleSprite = new Sprite(AssetManager.getTexture('info-bubble'));
        this.bubbleSprite.anchor.set(HTPNudgeView.POINTER_X_RATIO, 1);

        this.addChild(this.bubbleSprite);
    }

    private createText(labelText: string): void {
        this.bubbleText = new Text(labelText, {
            ...messageTextStyle,
            fontSize: 24,
            align: 'center'
        });

        this.bubbleText.anchor.set(0.5);
        this.addChild(this.bubbleText);
    }

    private scaleTextToFit(): void {
        const spriteWidth = this.bubbleSprite.width;
        const spriteHeight = this.bubbleSprite.height;

        if (spriteWidth === 0 || spriteHeight === 0) { return; }

        const availableWidth = spriteWidth * (1 - (HTPNudgeView.PADDING_PERCENTAGE * 2));
        // Exclude the pointer from available height -> text sits in the body portion only.
        const bodyHeight = spriteHeight * (1 - HTPNudgeView.POINTER_HEIGHT_RATIO);
        const availableHeight = bodyHeight * (1 - (HTPNudgeView.PADDING_PERCENTAGE * 2));

        this.bubbleText.scale.set(1);

        const widthScale = availableWidth / this.bubbleText.width;
        const heightScale = availableHeight / this.bubbleText.height;
        const scale = Math.min(widthScale, heightScale, 1);

        this.bubbleText.scale.set(scale);
    }
}
